qemu:

; ---- Subroutine: qemu.chrout ----
    ALIGN 2

qemu.chrout:
            move.l  d0,qemu.TTY_PUT_CHAR
            rts
; End of subroutine: qemu.chrout


; ---- Subroutine: qemu.chrin ----
    ALIGN 2

qemu.chrin:
            suba.l  #4,sp
            movea.l  sp,a0       ; buffer = stack pointer (in A0 for input_data)
            moveq   #1,d1        ; maxlen = 1
            bsr     qemu.input_data
            move.b  (sp),d0
            adda.l  #4,sp
            rts
; End of subroutine: qemu.chrin


; ---- Subroutine: qemu.keypressed ----
    ALIGN 2

qemu.keypressed:
            movea.l #qemu.TTY_BYTES_READY,a1
            move.l  (a1),d0
            tst.l   d0
            rts
; End of subroutine: qemu.keypressed


; ---- Subroutine: qemu.input_data ----
    ALIGN 2

qemu.input_data:
1$:         movea.l  #qemu.TTY_BYTES_READY,a1
            move.l   (a1),d0
            tst.l    d0
            beq      1$                  ; wait for at least 1 byte
            ; d0 = available bytes, d1 = maxlen
            cmp.l    d1,d0               ; available - maxlen
            bls      2$                  ; if available <= maxlen, keep d0
            move.l   d1,d0               ; else cap at maxlen
2$:         movea.l  #qemu.TTY_DATA_PTR,a1
            move.l   a0,(a1)
            movea.l  #qemu.TTY_DATA_LEN,a1
            move.l   d0,(a1)
            movea.l  #qemu.TTY_CMD,a1
            move.l   #qemu.TTY_CMD_READ_BUFFER,(a1)
            rts
; End of subroutine: qemu.input_data


; ---- Subroutine: qemu.puts ----
    ALIGN 2

qemu.puts:
            move.l  d0,-(sp)
            move.l  a0,-(sp)
.loop:
            move.b   (a0)+,d0
            beq      .done
            move.l   d0,qemu.TTY_PUT_CHAR
            bra.s    .loop
.done:
            move.l  (sp)+,a0
            move.l  (sp)+,d0
            rts
; End of subroutine: qemu.puts

; ---- Subroutine: qemu.bootinfo_ptr ----
; source: syslib.p8:136

    ALIGN 2

qemu.bootinfo_ptr:
        ; call sys.progend():r350.l@s18
            lea  prog8_program_end,a0
    move.l  a0,p8_regfile+708
        ; inc.l r350.l
    addq.l  #1,p8_regfile+708
        ; bitclr.l r350.l,#0.b
    bclr  #0,p8_regfile+711
        ; returnr.l r350.l
    move.l  p8_regfile+708,d0
    rts
; End of subroutine: qemu.bootinfo_ptr

; ---- Subroutine: qemu.bootinfo_next ----
; source: syslib.p8:143

    ALIGN 2

qemu.bootinfo_next:
        ; loadm.l r351.l,[qemu.bootinfo_next.ptr]
    move.l  qemu.bootinfo_next.ptr,p8_regfile+712
        ; loadi.w r352.w,[r351.p]
    movea.l  p8_regfile+712,a0
    move.w  (a0),d0
        ; storem.w r352.w,[qemu.bootinfo_next.tag]
    move.w  d0, qemu.bootinfo_next.tag
        ; loadm.w r353.w,[qemu.bootinfo_next.tag]
    move.w  qemu.bootinfo_next.tag,p8_regfile+718
        ; bstne p8_label_gen_83
    bne  p8_label_gen_83
; source: syslib.p8:145
        ; returni.l #0.l
    moveq  #0,d0
    rts

p8_label_gen_83:
; source: syslib.p8:146
        ; loadm.l r354.l,[qemu.bootinfo_next.ptr]
    move.l  qemu.bootinfo_next.ptr,p8_regfile+720
        ; add.l r354.l,#2.l
    addq.l  #2,p8_regfile+720
        ; loadi.w r355.w,[r354.p]
    movea.l  p8_regfile+720,a0
    move.w  (a0),d0
    move.w  d0,p8_regfile+724
        ; ext.w r356.l,r355.w
    moveq  #0,d0
    move.w  p8_regfile+724,d0
    move.l  d0,p8_regfile+726
        ; loadm.l r357.l,[qemu.bootinfo_next.ptr]
    move.l  qemu.bootinfo_next.ptr,p8_regfile+730
        ; addr.l r356.l,r357.l
    move.l  p8_regfile+730,d0
    add.l  d0,p8_regfile+726
        ; returnr.l r356.l
    move.l  p8_regfile+726,d0
    rts
; End of subroutine: qemu.bootinfo_next


; ---- Subroutine: qemu.bootinfo_dump ----
    ALIGN 2

qemu.bootinfo_dump:
            bsr     qemu.bootinfo_ptr
            movea.l d0,a2           ; a2 = first record
1$:         clr.l   d0
            move.w  (a2),d0         ; tag
            beq     9$              ; BI_LAST
            clr.l   d1
            move.w  2(a2),d1        ; total size
            move.l  d0,d4           ; save tag in d4
            move.l  d1,d5           ; save size in d5
            move.l  a2,a3           ; save current pointer
            move.l  a2,qemu.bootinfo_next.ptr    ; store ptr
            bsr     qemu.bootinfo_next
            movea.l d0,a2           ; a2 = next record

            ; print "REC "
            lea     .str_rec,a0
            bsr     qemu.puts
            ; print tag as 4-digit hex
            move.w  d4,d0           ; restore tag from d4 (16-bit)
            moveq   #3,d7
2$:         rol.w   #4,d0
            move.b  d0,d3
            and.b   #$f,d3
            add.b   #'0',d3
            cmp.b   #'9',d3
            bls     3$
            add.b   #7,d3
3$:         move.l  d3,qemu.TTY_PUT_CHAR
            dbra    d7,2$
            ; print " size="
            lea     .str_size,a0
            bsr     qemu.puts
            ; print size as 4-digit hex
            move.w  d5,d0           ; restore size (16-bit)
            moveq   #3,d7
4$:         rol.w   #4,d0
            move.b  d0,d3
            and.b   #$f,d3
            add.b   #'0',d3
            cmp.b   #'9',d3
            bls     5$
            add.b   #7,d3
5$:         move.l  d3,qemu.TTY_PUT_CHAR
            dbra    d7,4$
            ; print " data="
            lea     .str_data,a0
            bsr     qemu.puts
            ; print each data byte as 2-digit hex
            movea.l a3,a0
            adda.l  #4,a0           ; a0 -> data payload
            move.l  d5,d1
            subq.l  #4,d1           ; d1 = data size
            ble     7$              ; skip if size<=4 (no payload bytes)
            moveq   #0,d6
6$:         move.b  (a0)+,d3
            lsr.b   #4,d3
            add.b   #'0',d3
            cmp.b   #'9',d3
            bls     8$
            add.b   #7,d3
8$:         move.l  d3,qemu.TTY_PUT_CHAR
            move.b  -1(a0),d3
            and.b   #$f,d3
            add.b   #'0',d3
            cmp.b   #'9',d3
            bls     10$
            add.b   #7,d3
10$:        move.l  d3,qemu.TTY_PUT_CHAR
            move.b  #' ',d3
            move.l  d3,qemu.TTY_PUT_CHAR
            addq.l  #1,d6
            cmp.l   d1,d6
            blo     6$
7$:         ; newline (must use 32-bit write, goldfish TTY ignores byte writes)
            moveq   #10,d0
            move.l  d0,qemu.TTY_PUT_CHAR
            bra     1$

9$:         lea     .str_end,a0
            bra     qemu.puts

            ALIGN 2
.str_rec:   dc.b "REC ",0
            ALIGN 2
.str_size:  dc.b " size=",0
            ALIGN 2
.str_data:  dc.b " data=",0
            ALIGN 2
.str_end:   dc.b "--- end bootinfo ---",10,0
            ; !notreached!
; End of subroutine: qemu.bootinfo_dump


; Block: sys

sys:
; ---- Subroutine: sys.die ----
; source: syslib.p8:352

    ALIGN 2

sys.die:
            lea  sys.die.warning,a0
.loop1:
            move.b  (a0)+,d0
            beq  .done1
            move.l  d0,qemu.TTY_PUT_CHAR
            bra.s .loop1
.done1:
            move.l  sys.die.message,a0
.loop2:
            move.b  (a0)+,d0
            beq  .done2
            move.l  d0,qemu.TTY_PUT_CHAR
            bra.s  .loop2
.done2:
            moveq  #10,d0
            move.l  d0,qemu.TTY_PUT_CHAR
        ; loadm.w r358.w,[sys.die.code]
    move.w  sys.die.code,p8_regfile+734
        ; call sys.exit(r358.w@s10)
    move.w  p8_regfile+734,d0
    bra  sys.exit
        ; return
; End of subroutine: sys.die


; ---- Subroutine: sys.exit ----
    ALIGN 2

sys.exit:
            and.l    #$ffff,d0
            movea.l  #qemu.CTRL_REG_CMD,a1
            move.l   #qemu.CTRL_CMD_HALT,(a1)
            stop #0
            ; !notreached!
; End of subroutine: sys.exit


; ---- Subroutine: sys.exec_version ----
    ALIGN 2

sys.exec_version:
            moveq  #36,d0
            rts
; End of subroutine: sys.exec_version


; ---- Subroutine: sys.memcopy ----
    ALIGN 2

sys.memcopy:
            move.l   d0,d2
            beq      .done

            ; check if both addresses share the same alignment offset
            move.l   a0,d0
            move.l   a1,d3
            eor.l    d3,d0
            andi.l   #3,d0
            bne      .bytes

            ; same alignment: pre-align both to a long boundary
            move.l   a0,d3
            and.w    #3,d3             ; d3 = offset (0-3)
            beq      .bulk
.loop_pre:
            move.b   (a0)+,(a1)+
            subq.l   #1,d2             ; track remaining count
            beq      .done
            move.l   a0,d3
            andi.l   #3,d3
            bne      .loop_pre

.bulk:
            move.l   d2,d3
            lsr.l    #2,d3             ; d3 = longword count
            beq      .rem
.loop_l:
            move.l   (a0)+,(a1)+
            subq.l   #1,d3
            bne      .loop_l

.rem:
            andi.l   #3,d2
            beq      .done
.loop_rem:
            move.b   (a0)+,(a1)+
            subq.l   #1,d2
            bne      .loop_rem
.done:
            rts

.bytes:
            subq.l   #1,d2
.loop_b:
            move.b   (a0)+,(a1)+
            subq.l   #1,d2
            bne      .loop_b
            rts
; End of subroutine: sys.memcopy


; ---- Subroutine: sys.stack_size ----
    ALIGN 2

sys.stack_size:
            move.l  sp,d0
            lea     prog8_program_end,a0
            sub.l   a0,d0
            rts
; End of subroutine: sys.stack_size


; ---- Subroutine: sys.cpuAtLeast68020 ----
    ALIGN 2

sys.cpuAtLeast68020:
            moveq   #0,d0       ; qemu68k always targets a 68020 or newer
            rts
; End of subroutine: sys.cpuAtLeast68020


; ---- Subroutine: sys.memset ----
    ALIGN 2

sys.memset:
            movea.l  d0,a0
            tst.w    d1
            beq      .done
            tst.b    d2
            beq      sys.memclear       ; tail-call: value==0

            ; save fill byte zero-extended
            moveq    #0,d3
            move.b   d2,d3

            ; align address to even for word/longword transfers
            move.l   a0,d0
            btst     #0,d0
            beq      .aligned
            move.b   d3,(a0)+
            subq.l   #1,d1
            beq      .done

.aligned:
            ; expand fill byte to all byte positions in d3
            move.l   d3,d0
            lsl.l    #8,d0
            or.l     d0,d3
            move.l   d3,d0
            swap     d0
            or.l     d0,d3

            ; longword fill (4 bytes per iteration)
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numbytes (zero-extended)
            lsr.l    #2,d0
            beq      .bytes
            subq.w   #1,d0
.loop_l:
            move.l   d3,(a0)+
            dbra     d0,.loop_l

            ; remaining bytes (0-3)
.bytes:
            and.w    #3,d1
            beq      .done
            subq.w   #1,d1
.loop_b:
            move.b   d3,(a0)+
            dbra     d1,.loop_b
.done:
            rts
; End of subroutine: sys.memset


; ---- Subroutine: sys.memclear ----
    ALIGN 2

sys.memclear:
            movea.l  d0,a0
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numbytes (zero-extended)
            beq      .done

            ; align to even for word/longword access
            move.l   a0,d1
            btst     #0,d1
            beq      .compute
            clr.b    (a0)+
            subq.l   #1,d0
            beq      .done

.compute:
            move.l   d0,d1
            move.l   d1,d2
            and.w    #31,d2          ; d2 = tail bytes after 32-byte blocks
            lsr.l    #5,d1           ; d1 = number of 32-byte blocks
            move.l   d2,a2           ; a2 = tail bytes
            movea.l  d1,a1           ; a1 = block count (save before zeroing regs)

            ; point a0 past the last byte, so we can decrement with movem
            move.l   d1,d3
            lsl.l    #5,d3
            adda.l   d3,a0           ; a0 = end address
            movea.l  a0,a4           ; a4 = end address; the movem loop leaves a0 back at the start

            ; zero all data registers except d7 (d7 will be the loop counter, not in movem)
            move.l   d1,d7           ; d7 = block count (save before zeroing)
            moveq    #0,d0
            move.l   d0,d1
            move.l   d0,d2
            move.l   d0,d3
            move.l   d0,d4
            move.l   d0,d5
            move.l   d0,d6
            movea.l  d0,a1           ; also zero a1 (part of movem)

            ; bulk clear: 32 bytes per movem (d0-d6=28 bytes + a1=4 bytes), decrementing a0
            subq.w   #1,d7
            bmi      .tail
.loop_m:
            movem.l  d0-d6/a1,-(a0)
            dbra     d7,.loop_m

.tail:
            movea.l  a4,a0           ; a0 = end of the bulk region, where the tail bytes belong
            movea.l  a2,a3
            move.l   a3,d0           ; copy to data reg for shift/btst
            beq      .done
            move.l   d0,d1
            lsr.l    #2,d1           ; d1 = longwords in tail
            beq      .tail_words
            subq.l   #1,d1
.loop_l:
            clr.l    (a0)+
            subq.l   #1,d1
            bpl      .loop_l

.tail_words:
            btst     #1,d0
            beq      .tail_byte
            clr.w    (a0)+

.tail_byte:
            btst     #0,d0
            beq      .done
            clr.b    (a0)+
.done:
            rts
; End of subroutine: sys.memclear


; ---- Subroutine: sys.memsetw ----
    ALIGN 2

sys.memsetw:
            movea.l  d0,a0
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numwords (zero-extended)
            beq      .done
            move.w   d2,d1           ; d1 = fill word value

            ; Create longword fill pattern: d1:d1
            move.w   d1,d2
            swap     d2
            move.w   d1,d2           ; d2 = d1 : d1

            ; longword fill (2 words at a time)
            move.l   d0,d3
            lsr.l    #1,d3           ; d3 = numwords / 2
            beq      .odd_word
            subq.w   #1,d3
.loop_l:
            move.l   d2,(a0)+
            dbra     d3,.loop_l

.odd_word:
            btst     #0,d0
            beq      .done
            move.w   d1,(a0)+

.done:
            rts
; End of subroutine: sys.memsetw


; ---- Subroutine: sys.memsetl ----
    ALIGN 2

sys.memsetl:
            movea.l  d0,a0
            moveq    #0,d0
            move.w   d1,d0           ; d0 = numlongs (zero-extended)
            beq      .done

            ; longword fill
            subq.w   #1,d0
.loop_l:
            move.l   d2,(a0)+
            dbra     d0,.loop_l

.done:
            rts
; End of subroutine: sys.memsetl


; Block: prog8_math

prog8_math:
; 68000 math routines that should always be included by the compiler

  SECTION .bss,bss

math._sqrt_l.value:    ds.l 1
math._sqrt_uw.value:   ds.w 1
math._sqrt_ub.value:   ds.b 1

  SECTION .text,code  ; back to code section


math._sqrt_ub:
    moveq  #0,d1
    clr.l  d0
    move.b  math._sqrt_ub.value,d0
    beq  .done_ub
    moveq  #4,d2
.loop_ub:
    move.l  d1,d3
    bset  d2,d3
    mulu.w  d3,d3
    cmp.w  d0,d3
    bhi  .skip_ub
    bset  d2,d1
.skip_ub:
    subq  #1,d2
    bpl  .loop_ub
.done_ub:
    move.b  d1,d0
    rts

math._sqrt_uw:
    moveq  #0,d1
    move.w  math._sqrt_uw.value,d0
    beq  .done_uw
    moveq  #8,d2
.loop_uw:
    move.l  d1,d3
    bset  d2,d3
    mulu.w  d3,d3
    cmp.l  d0,d3
    bhi  .skip_uw
    bset  d2,d1
.skip_uw:
    subq  #1,d2
    bpl  .loop_uw
.done_uw:
    move.b  d1,d0
    rts

math._sqrt_l:
    moveq  #0,d1
    move.l  math._sqrt_l.value,d0
    beq  .done_l
    moveq  #15,d2
.loop_l:
    move.l  d1,d3
    bset  d2,d3
    mulu.w  d3,d3
    cmp.l  d0,d3
    bhi  .skip_l
    bset  d2,d1
.skip_l:
    subq  #1,d2
    bpl  .loop_l
.done_l:
    move.w  d1,d0
    rts

